import db from "~/db.server";

function parseSafe<T>(str: string, fallback: T): T {
  try { return JSON.parse(str) as T; } catch { return fallback; }
}

function slugify(text: string): string {
  return text.toLowerCase().replace(/[^a-z0-9\s-]/g, "").replace(/\s+/g, "-").replace(/-+/g, "-").replace(/^-|-$/g, "") || "quiz";
}

async function generateUniqueSlug(shop: string, title: string, excludeId?: string): Promise<string> {
  const base = slugify(title);
  let slug = base;
  let counter = 0;
  while (true) {
    const existing = await db.quiz.findFirst({ where: { shop, slug, ...(excludeId ? { NOT: { id: excludeId } } : {}) } });
    if (!existing) break;
    counter++;
    slug = `${base}-${counter}`;
  }
  return slug;
}

export async function getQuizzes(shop: string) {
  return db.quiz.findMany({
    where: { shop, status: { not: "archived" } },
    orderBy: { createdAt: "desc" },
    include: { _count: { select: { questions: true, responses: true } } },
  });
}

export async function getQuizById(id: string, shop: string) {
  return db.quiz.findFirst({
    where: { id, shop },
    include: {
      questions: {
        include: { answers: { orderBy: { position: "asc" } } },
        orderBy: { position: "asc" },
      },
      resultPages: { orderBy: { position: "asc" } },
      _count: { select: { responses: true } },
    },
  });
}

export async function createQuiz(shop: string, data: { title: string; type?: string; description?: string }) {
  const slug = await generateUniqueSlug(shop, data.title);
  return db.quiz.create({
    data: {
      shop,
      slug,
      title: data.title,
      type: data.type ?? "product-recommendation",
      description: data.description,
    },
  });
}

export async function updateQuiz(id: string, shop: string, data: {
  title?: string;
  description?: string | null;
  status?: string;
  settings?: string;
