import db from "~/db.server";

export async function createQuestion(quizId: string, shop: string, data: {
  type: string;
  title: string;
  description?: string;
  required?: boolean;
}) {
  // Verify quiz ownership
  const quiz = await db.quiz.findFirst({ where: { id: quizId, shop } });
  if (!quiz) throw new Error("Quiz not found");

  const count = await db.question.count({ where: { quizId } });

  return db.question.create({
    data: {
      quizId,
      type: data.type,
      title: data.title,
      description: data.description,
      required: data.required ?? true,
      position: count,
    },
    include: { answers: { orderBy: { position: "asc" } } },
  });
}

export async function updateQuestion(id: string, quizId: string, shop: string, data: {
  title?: string;
  type?: string;
  description?: string | null;
  required?: boolean;
  settings?: string;
}) {
  const quiz = await db.quiz.findFirst({ where: { id: quizId, shop } });
  if (!quiz) throw new Error("Quiz not found");

  return db.question.update({
    where: { id },
    data,
  });
}

export async function deleteQuestion(id: string, quizId: string, shop: string): Promise<void> {
  const quiz = await db.quiz.findFirst({ where: { id: quizId, shop } });
  if (!quiz) throw new Error("Quiz not found");
  await db.question.delete({ where: { id } });

  // Reorder remaining questions
  const remaining = await db.question.findMany({
    where: { quizId },
    orderBy: { position: "asc" },
  });
  await Promise.all(
    remaining.map((q, i) => db.question.update({ where: { id: q.id }, data: { position: i } }))
  );
}

export async function reorderQuestions(quizId: string, shop: string, questionIds: string[]): Promise<void> {
  const quiz = await db.quiz.findFirst({ where: { id: quizId, shop } });
  if (!quiz) throw new Error("Quiz not found");

  await Promise.all(
    questionIds.map((id, position) => db.question.update({ where: { id }, data: { position } }))
  );
}

export async function createAnswer(questionId: string, quizId: string, shop: string, data: {
  text: string;
  imageUrl?: string;
  score?: number;
  productTags?: string[];
}) {
  const quiz = await db.quiz.findFirst({ where: { id: quizId, shop } });
  if (!quiz) throw new Error("Quiz not found");

  const count = await db.answer.count({ where: { questionId } });

  return db.answer.create({
    data: {
      questionId,
      text: data.text,
      imageUrl: data.imageUrl,
      score: data.score ?? 0,
      productTags: JSON.stringify(data.productTags ?? []),
      position: count,
    },
