export async function updateAnswer(id: string, questionId: string, quizId: string, shop: string, data: {
  text?: string;
  score?: number;
  productTags?: string[];
}) {
  const quiz = await db.quiz.findFirst({ where: { id: quizId, shop } });
  if (!quiz) throw new Error("Quiz not found");

  return db.answer.update({
    where: { id },
    data: {
      text: data.text,
      score: data.score,
      ...(data.productTags !== undefined ? { productTags: JSON.stringify(data.productTags) } : {}),
    },
  });
}

export async function deleteAnswer(id: string, questionId: string, quizId: string, shop: string): Promise<void> {
  const quiz = await db.quiz.findFirst({ where: { id: quizId, shop } });
  if (!quiz) throw new Error("Quiz not found");
  await db.answer.delete({ where: { id } });
}

export async function saveQuestionsAndAnswers(quizId: string, shop: string, questions: Array<{
  id?: string;
  title: string;
  type: string;
  required: boolean;
  position: number;
  answers: Array<{
    id?: string;
    text: string;
    score: number;
    productTags: string[];
    position: number;
  }>;
}>) {
  const quiz = await db.quiz.findFirst({ where: { id: quizId, shop } });
  if (!quiz) throw new Error("Quiz not found");

  // Delete all existing questions (cascade deletes answers)
  await db.question.deleteMany({ where: { quizId } });

  // Create new ones in order
  for (const q of questions) {
    await db.question.create({
      data: {
        quizId,
        title: q.title,
        type: q.type,
        required: q.required,
        position: q.position,
        answers: {
          create: q.answers.map((a) => ({
            text: a.text,
            score: a.score,
            productTags: JSON.stringify(a.productTags),
            position: a.position,
          })),
        },
      },
    });
  }
}
