import db from "~/db.server";
import { PLAN_LIMITS, PLAN_FEATURES, type PlanId } from "~/utils/constants";
import { json } from "react-router";

export async function getSubscription(shop: string) {
  return db.subscription.findUnique({ where: { shop } });
}

export async function getPlanId(shop: string): Promise<PlanId> {
  const sub = await db.subscription.findUnique({
    where: { shop },
    select: { planId: true, status: true },
  });
  if (!sub || sub.status !== "active") return "free";
  const validPlans = Object.keys(PLAN_LIMITS) as PlanId[];
  return validPlans.includes(sub.planId as PlanId) ? (sub.planId as PlanId) : "free";
}

export async function requirePlan(shop: string, minimumPlan: PlanId): Promise<void> {
  const planOrder: PlanId[] = ["free", "starter", "pro", "enterprise"];
  const currentPlan = await getPlanId(shop);
  if (planOrder.indexOf(currentPlan) < planOrder.indexOf(minimumPlan)) {
    throw json(
      { error: `This feature requires the ${minimumPlan} plan or higher.`, requiredPlan: minimumPlan, currentPlan },
      { status: 403 }
    );
  }
}

export async function checkQuizLimit(shop: string): Promise<void> {
  const planId = await getPlanId(shop);
  const limit = PLAN_LIMITS[planId].quizLimit;
  if (limit === Infinity) return;
  const count = await db.quiz.count({ where: { shop, status: { not: "archived" } } });
  if (count >= limit) {
    throw json(
      { error: `You've reached the ${limit}-quiz limit for the ${planId} plan.`, currentPlan: planId, limit, current: count },
      { status: 403 }
    );
  }
}

export async function ensureSubscription(shop: string) {
  return db.subscription.upsert({
    where: { shop },
    create: { shop, planId: "free", status: "active", quizLimit: 1, responseLimit: 100 },
    update: {},
  });
}
