import db from "~/db.server";

export async function getAnalyticsSummary(shop: string, days: number = 30) {
  const from = new Date();
  from.setDate(from.getDate() - days);
  const prevFrom = new Date();
  prevFrom.setDate(prevFrom.getDate() - days * 2);

  const [completions, starts, revenue, emails, prevCompletions, quizStats] = await Promise.all([
    db.quizResponse.count({ where: { shop, completedAt: { not: null }, createdAt: { gte: from } } }),
    db.quizResponse.count({ where: { shop, createdAt: { gte: from } } }),
    db.quizResponse.aggregate({ where: { shop, createdAt: { gte: from } }, _sum: { revenue: true } }),
    db.quizResponse.count({ where: { shop, email: { not: null }, createdAt: { gte: from } } }),
    db.quizResponse.count({ where: { shop, completedAt: { not: null }, createdAt: { gte: prevFrom, lt: from } } }),
    db.quiz.findMany({
      where: { shop, status: { not: "archived" } },
      select: { id: true, title: true, completions: true },
      orderBy: { completions: "desc" },
      take: 5,
    }),
  ]);

  const totalRevenue = revenue._sum.revenue ?? 0;
  const completionRate = starts > 0 ? completions / starts : 0;
  const prevTrend = prevCompletions > 0 ? ((completions - prevCompletions) / prevCompletions * 100).toFixed(1) : "0";

  return {
    completions,
    starts,
    completionRate,
    revenue: totalRevenue,
    emailsCaptured: emails,
    trend: `${Number(prevTrend) >= 0 ? "+" : ""}${prevTrend}%`,
    topQuizzes: quizStats,
  };
}

export async function getDailyStats(shop: string, days: number = 7) {
  const from = new Date();
  from.setDate(from.getDate() - days);
  from.setHours(0, 0, 0, 0);

  const responses = await db.quizResponse.findMany({
    where: { shop, createdAt: { gte: from } },
    select: { createdAt: true, completedAt: true },
  });

  const byDate: Record<string, { started: number; completed: number }> = {};
  for (const r of responses) {
    const date = r.createdAt.toISOString().split("T")[0];
    if (!byDate[date]) byDate[date] = { started: 0, completed: 0 };
    byDate[date].started++;
    if (r.completedAt) byDate[date].completed++;
  }

  return Object.entries(byDate)
    .sort(([a], [b]) => a.localeCompare(b))
    .map(([date, stats]) => ({
      date: new Intl.DateTimeFormat("en-US", { month: "short", day: "numeric" }).format(new Date(date)),
      ...stats,
    }));
}
