import db from "~/db.server";

function slugify(text: string): string {
  return (
    text
      .toLowerCase()
      .replace(/[^a-z0-9\s-]/g, "")
      .replace(/\s+/g, "-")
      .replace(/-+/g, "-")
      .replace(/^-|-$/g, "") || "quiz"
  );
}

async function generateUniqueSlug(
  shop: string,
  title: string,
  excludeId?: string
): Promise<string> {
  const base = slugify(title);
  let slug = base;
  let counter = 0;
  while (true) {
    const existing = await db.quiz.findFirst({
      where: {
        shop,
        slug,
        ...(excludeId ? { NOT: { id: excludeId } } : {}),
      },
    });
    if (!existing) break;
    counter++;
    slug = `${base}-${counter}`;
  }
  return slug;
}

export async function getQuizzes(shop: string) {
  return db.quiz.findMany({
    where: { shop, status: { not: "archived" } },
    orderBy: { createdAt: "desc" },
    include: {
      _count: { select: { questions: true, responses: true } },
    },
  });
}

export async function getQuizById(id: string, shop: string) {
