export async function syncToEmailProvider(
  shop: string,
  email: string,
  quizData: QuizEmailData
): Promise<void> {
  const integrations = await db.emailIntegration.findMany({
    where: { shop, isActive: true },
  });

  for (const integration of integrations) {
    try {
      if (integration.provider === "klaviyo") {
        await syncToKlaviyo(
          integration.apiKey,
          integration.listId ?? "",
          email,
          quizData
        );
      } else if (integration.provider === "mailchimp") {
        const serverPrefix = integration.apiKey.split("-")[1] ?? "us1";
        await syncToMailchimp(
          integration.apiKey,
          serverPrefix,
          integration.listId ?? "",
          email,
          quizData
        );
      }
    } catch (error) {
      console.error(`${integration.provider} sync failed:`, error);
      // Non-fatal — continue with next integration
    }
  }
}

async function syncToKlaviyo(
  apiKey: string,
  listId: string,
  email: string,
  quizData: Pick<QuizEmailData, "quizTitle" | "resultPageTitle" | "productTags">
): Promise<void> {
  const payload = {
    data: {
      type: "profile-subscription-bulk-create-job",
      attributes: {
        profiles: {
          data: [
            {
              type: "profile",
              attributes: {
                email,
                properties: {
                  quiz_result: quizData.resultPageTitle,
                  quiz_name: quizData.quizTitle,
                  quiz_tags: quizData.productTags.join(", "),
                },
              },
            },
          ],
        },
        ...(listId
          ? {
              relationships: {
                list: { data: { type: "list", id: listId } },
              },
            }
          : {}),
      },
    },
  };

  const response = await fetch(
    "https://a.klaviyo.com/api/profile-subscription-bulk-create-jobs/",
    {
      method: "POST",
      headers: {
        Authorization: `Klaviyo-API-Key ${apiKey}`,
        "Content-Type": "application/json",
        revision: "2024-10-15",
      },
      body: JSON.stringify(payload),
      signal: AbortSignal.timeout(10000),
    }
  );

  if (!response.ok) {
    throw new Error(`Klaviyo API error: ${response.status}`);
  }
}

async function syncToMailchimp(
  apiKey: string,
  serverPrefix: string,
  audienceId: string,
  email: string,
  quizData: Pick<QuizEmailData, "quizTitle" | "quizSlug" | "resultPageTitle">
): Promise<void> {
  const crypto = await import("crypto");
  const emailHash = crypto
    .createHash("md5")
    .update(email.toLowerCase())
    .digest("hex");

  const memberData = {
    email_address: email,
    status_if_new: "subscribed",
    tags: [
      `quiz-${quizData.quizSlug}`,
      `result-${quizData.resultPageTitle.toLowerCase().replace(/\s+/g, "-")}`,
    ],
  };

  const response = await fetch(
    `https://${serverPrefix}.api.mailchimp.com/3.0/lists/${audienceId}/members/${emailHash}`,
    {
      method: "PUT",
      headers: {
        Authorization: `Bearer ${apiKey}`,
        "Content-Type": "application/json",
      },
      body: JSON.stringify(memberData),
      signal: AbortSignal.timeout(10000),
    }
  );

  if (!response.ok) {
    throw new Error(`Mailchimp API error: ${response.status}`);
  }
}

